// ratelimit_test.go
package ratelimit

import (
	"errors"
	"testing"
	"time"
)

type fakeClock struct {
	t time.Time
}

func (f *fakeClock) Now() time.Time { return f.t }
func (f *fakeClock) Advance(d time.Duration) {
	f.t = f.t.Add(d)
}

func TestNewLimiterValidation(t *testing.T) {
	tests := []struct {
		name    string
		rate    float64
		burst   float64
		clock   Clock
		wantErr error
	}{
		{"zero rate", 0, 1, nil, ErrNonPositiveRate},
		{"negative rate", -1, 1, nil, ErrNonPositiveRate},
		{"zero burst", 1, 0, nil, ErrNonPositiveBurst},
		{"negative burst", 1, -1, nil, ErrNonPositiveBurst},
		{"nil clock ok", 1, 1, nil, nil},
		{"valid", 2, 5, &fakeClock{}, nil},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			l, err := NewLimiter(tc.rate, tc.burst, tc.clock)
			if tc.wantErr == nil {
				if err != nil {
					t.Fatalf("unexpected error: %v", err)
				}
				if l == nil {
					t.Fatal("expected non-nil limiter")
				}
				return
			}
			if !errors.Is(err, tc.wantErr) {
				t.Fatalf("got error %v, want %v", err, tc.wantErr)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)

	tests := []struct {
		name  string
		rate  float64
		burst float64
		steps []struct {
			advance time.Duration
			n       float64
			want    bool
		}
	}{
		{
			name:  "burst available then exhausted",
			rate:  1,
			burst: 2,
			steps: []struct {
				advance time.Duration
				n       float64
				want    bool
			}{
				{0, 1, true},
				{0, 1, true},
				{0, 1, false},
			},
		},
		{
			name:  "refill over time",
			rate:  1,
			burst: 1,
			steps: []struct {
				advance time.Duration
				n       float64
				want    bool
			}{
				{0, 1, true},
				{0, 1, false},
				{time.Second, 1, true},
				{500 * time.Millisecond, 1, false},
				{500 * time.Millisecond, 1, true},
			},
		},
		{
			name:  "tokens capped at burst",
			rate:  10,
			burst: 2,
			steps: []struct {
				advance time.Duration
				n       float64
				want    bool
			}{
				{0, 2, true},
				{10 * time.Second, 3, false}, // only 2 accumulated
				{0, 2, true},
			},
		},
		{
			name:  "fractional refill",
			rate:  2,
			burst: 1,
			steps: []struct {
				advance time.Duration
				n       float64
				want    bool
			}{
				{0, 1, true},
				{250 * time.Millisecond, 1, false}, // 0.5 tokens
				{250 * time.Millisecond, 1, true},  // 1.0 tokens
			},
		},
		{
			name:  "negative request denied",
			rate:  1,
			burst: 1,
			steps: []struct {
				advance time.Duration
				n       float64
				want    bool
			}{
				{0, -1, false},
				{0, 1, true},
			},
		},
		{
			name:  "request larger than burst denied",
			rate:  1,
			burst: 1,
			steps: []struct {
				advance time.Duration
				n       float64
				want    bool
			}{
				{time.Hour, 2, false},
			},
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			fc := &fakeClock{t: base}
			l, err := NewLimiter(tc.rate, tc.burst, fc)
			if err != nil {
				t.Fatalf("NewLimiter: %v", err)
			}
			for i, s := range tc.steps {
				fc.Advance(s.advance)
				if got := l.AllowN(fc.Now(), s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%v) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestConcurrentUse(t *testing.T) {
	fc := &fakeClock{t: time.Now()}
	l, err := NewLimiter(1000, 100, fc)
	if err != nil {
		t.Fatal(err)
	}
	done := make(chan struct{})
	for i := 0; i < 8; i++ {
		go func() {
			defer func() { done <- struct{}{} }()
			for j := 0; j < 1000; j++ {
				l.AllowN(fc.Now(), 0.001)
			}
		}()
	}
	for i := 0; i < 8; i++ {
		<-done
	}
	if l.tokens < 0 || l.tokens > l.burst {
		t.Fatalf("tokens out of range: %v", l.tokens)
	}
}
